verus! {
    use vstd::vec;

    /// Replaces elements in the input array based on the threshold.
    /// If an element is greater than the threshold, it is replaced with -1.
    /// Otherwise, it remains unchanged.
    #[verifier::spec]
    fn replace(arr: &Vec<i32>, k: i32) -> Vec<i32> 
        ensures |output: &Vec<i32>| {
            // The output length must equal the input length
            output.len() == arr.len() &&
            // For every index i, if arr[i] > k then output[i] = -1, else output[i] = arr[i]
            forall(|i: usize| {
                (i < arr.len() ==> (arr[i] > k ==> output[i] == -1)) &&
                (i < arr.len() ==> (arr[i] <= k ==> output[i] == arr[i]))
            })
        }
    {
        let n = arr.len();
        let mut output = vec![0; n]; // Initialize output array with zeros

        // Iterate over the input array
        for i in 0..n {
            // Check if the current element is greater than the threshold
            if arr[i] > k {
                output[i] = -1; // Replace with -1
            } else {
                output[i] = arr[i]; // Keep the original value
            }
        }

        output // Return the modified output array
    }
}